        en: "O my God, I firmly believe that You are one God in three Divine Persons, Father, Son, and Holy Spirit. I believe that Your divine Son became man, died for our sins, and that He will come to judge the living and the dead. I believe these and all the truths that the holy Catholic Church teaches, because You have revealed them, Who can neither deceive nor be deceived.",
        it: "Mio Dio, credo fermamente che Tu sei un solo Dio in tre Persone divine: Padre, Figlio e Spirito Santo. Credo che il Tuo divin Figlio si è fatto uomo, è morto per i nostri peccati, e che Egli verrà a giudicare i vivi e i morti. Credo a queste verità e a tutte quelle che la Santa Chiesa Cattolica insegna, perché Tu le hai rivelate, Tu che non puoi ingannarti né ingannare.",
