        en: "O my God, I am heartily sorry for having offended You, and I detest all my sins because I dread the loss of heaven and the pains of hell, but most of all because they offend You, my God, Who are all-good and deserving of all my love. I firmly resolve, with the help of Your grace, to confess my sins, to do penance, and to amend my life. Amen.",
        it: "Mio Dio, mi pento e mi dolgo con tutto il cuore dei miei peccati, perché peccando ho meritato i Tuoi castighi, e molto più perché ho offeso Te, infinitamente buono e degno di essere amato sopra ogni cosa. Propongo, col Tuo santo aiuto, di non offenderti mai più e di fuggire le occasioni prossime di peccato. Signore, misericordia, perdonami.",
