// utils/dateUtils.js
export const formatDate = (date) => {
  return date.toISOString().split("T")[0]; // Returns 'YYYY-MM-DD'
};

export function findFeastsByDate(date, feasts, exact = false) {
  const isoDate = date.toISOString().split("T")[0]; // 'YYYY-MM-DD'
  const monthDay = isoDate.slice(5); // 'MM-DD'
  if (exact) {
    // Only exact match for today (online API might have it)
    return feasts.filter((feast) => feast.date === isoDate);
  } else {
    // Fallback: match any feast with matching month-day
    return feasts.filter((feast) => {
      // Accept both 'YYYY-MM-DD' and 'MM-DD' in feast.date
      const feastMonthDay =
        feast.date.length === 10 ? feast.date.slice(5) : feast.date;
      return feastMonthDay === monthDay;
    });
  }
}

